#include <memory>
#include <iostream>

int main() {
    std::unique_ptr<int> ptr1(new int(42));  // Non-null unique_ptr
    std::unique_ptr<int> ptr2;              // Null unique_ptr

    if (ptr1 == nullptr) {
        std::cout << "ptr1 is null" << std::endl;  // This won't execute
    } else {
        std::cout << "ptr1 is not null" << std::endl;  // This will execute
    }

    if (ptr2 != nullptr) {
        std::cout << "ptr2 is not null" << std::endl;  // This won't execute
    } else {
        std::cout << "ptr2 is null" << std::endl;  // This will execute
    }

    // Attempting operator< with nullptr is not standard, but for illustration:
    // This would not compile as written; use == or != instead.
    return 0;
}
